mapper.select:
select
studyhall.*,
types.type_name
from studyhall studyhall
left join types types on studyhall.type_id = types.id

    and studyhall.id = #{id}
    and studyhall.name like concat('%',#{name},'%')
    and studyhall.info = #{info}
    and studyhall.address = #{address}
    and studyhall.status = #{status}
    and studyhall.img = #{img}
    and studyhall.num = #{num}
    and studyhall.current_num = #{currentNum}
    and studyhall.create_time = #{createTime}
    and studyhall.type_id = #{typeId}
    and types.type_name like concat('%',#{typeName},'%')


    limit #{current},#{pageSize}

select count(*) from studyhall studyhall
left join types types on studyhall.type_id = types.id

    and studyhall.id = #{id}
    and studyhall.name like concat('%',#{name},'%')
    and studyhall.info = #{info}
    and studyhall.address = #{address}
    and studyhall.status = #{status}
    and studyhall.img = #{img}
    and studyhall.num = #{num}
    and studyhall.current_num = #{currentNum}
    and studyhall.create_time = #{createTime}
    and studyhall.type_id = #{typeId}
    and types.type_name like concat('%',#{typeName},'%')
